import { useEffect, useState } from 'react';
import './Profile.css';

import {
  getCountries,
  createCountry,
  updateCountry,
  deleteCountry
} from '../../services/countryService';

import {
  getCities,
  createCity,
  deleteCity
} from '../../services/cityService';

import {
  getCategories,
  createCategory,
  updateCategory,
  deleteCategory
} from '../../services/categoryService';

import {
  getTourOperators,
  createTourOperator,
  updateTourOperator,
  deleteTourOperator
} from '../../services/tourOperatorService';

import {
  getTags,
  createTag,
  updateTag,
  deleteTag
} from '../../services/tagService';

import {
  getTours,
  createTour,
  updateTour,
  deleteTour
} from '../../services/tourService';

const AdminPanel = () => {
  /* ===== DATA ===== */
  const [countries, setCountries] = useState([]);
  const [cities, setCities] = useState([]);
  const [categories, setCategories] = useState([]);
  const [operators, setOperators] = useState([]);
  const [tags, setTags] = useState([]);
  const [tours, setTours] = useState([]);

  /* ===== FORM STATE ===== */
  const [newCountry, setNewCountry] = useState('');
  const [newCity, setNewCity] = useState('');
  const [cityCountryId, setCityCountryId] = useState('');
  const [newCategory, setNewCategory] = useState('');
  const [newOperator, setNewOperator] = useState('');
  const [newTag, setNewTag] = useState('');

  const [tourForm, setTourForm] = useState({
    title: '',
    description: '',
    price: '',
    startDate: '',
    endDate: '',
    cityId: '',
    categoryId: '',
    tourOperatorId: ''
  });

  /* ===== LOAD ===== */
  useEffect(() => {
    loadAll();
  }, []);

  const loadAll = async () => {
    await Promise.all([
      loadCountries(),
      loadCities(),
      loadCategories(),
      loadOperators(),
      loadTags(),
      loadTours()
    ]);
  };

  const loadCountries = async () => setCountries(await getCountries());
  const loadCities = async () => setCities(await getCities());
  const loadCategories = async () => setCategories(await getCategories());
  const loadOperators = async () => setOperators(await getTourOperators());
  const loadTags = async () => setTags(await getTags());
  const loadTours = async () => setTours(await getTours());

  /* ===== TOUR HANDLERS ===== */
  const handleTourChange = (field, value) => {
    setTourForm(prev => ({ ...prev, [field]: value }));
  };

  const handleCreateTour = async () => {
    try {
      await createTour({
        ...tourForm,
        price: Number(tourForm.price),
        cityId: Number(tourForm.cityId),
        categoryId: Number(tourForm.categoryId),
        tourOperatorId: Number(tourForm.tourOperatorId)
      });

      alert('Экскурсия создана');
      setTourForm({
        title: '',
        description: '',
        price: '',
        startDate: '',
        endDate: '',
        cityId: '',
        categoryId: '',
        tourOperatorId: ''
      });

      loadTours();
    } catch {
      alert('Ошибка создания экскурсии');
    }
  };

  const handleEditTour = async (tour) => {
    const title = prompt('Новое название', tour.title);
    if (!title) return;

    await updateTour(tour.id, { ...tour, title });
    loadTours();
  };

  const handleDeleteTour = async (id) => {
    if (!window.confirm('Удалить экскурсию?')) return;
    await deleteTour(id);
    loadTours();
  };

  /* ===== TAG HANDLERS ===== */
  const handleAddTag = async () => {
    if (!newTag.trim()) return;
    await createTag(newTag.trim());
    setNewTag('');
    loadTags();
  };

  const handleEditTag = async (tag) => {
    const name = prompt('Новое название тега', tag.name);
    if (!name || name === tag.name) return;
    await updateTag(tag.id, name);
    loadTags();
  };

  const handleDeleteTag = async (id) => {
    if (!window.confirm('Удалить тег?')) return;
    await deleteTag(id);
    loadTags();
  };

  return (
    <div className="page">
      <div className="page-container">
        <h1 className="page-title">Панель администратора</h1>

        <div className="admin-grid">

          {/* ===== TOURS ===== */}
          <section className="admin-card">
            <h2>Экскурсии</h2>

            <input placeholder="Название" value={tourForm.title}
              onChange={e => handleTourChange('title', e.target.value)} />

            <textarea placeholder="Описание" value={tourForm.description}
              onChange={e => handleTourChange('description', e.target.value)} />

            <input type="number" placeholder="Цена" value={tourForm.price}
              onChange={e => handleTourChange('price', e.target.value)} />

            <input type="date" value={tourForm.startDate}
              onChange={e => handleTourChange('startDate', e.target.value)} />

            <input type="date" value={tourForm.endDate}
              onChange={e => handleTourChange('endDate', e.target.value)} />

            <select value={tourForm.cityId}
              onChange={e => handleTourChange('cityId', e.target.value)}>
              <option value="">Город</option>
              {cities.map(c => (
                <option key={c.id} value={c.id}>
                  {c.name} ({c.country?.name})
                </option>
              ))}
            </select>

            <select value={tourForm.categoryId}
              onChange={e => handleTourChange('categoryId', e.target.value)}>
              <option value="">Категория</option>
              {categories.map(c => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>

            <select value={tourForm.tourOperatorId}
              onChange={e => handleTourChange('tourOperatorId', e.target.value)}>
              <option value="">Туроператор</option>
              {operators.map(o => (
                <option key={o.id} value={o.id}>{o.name}</option>
              ))}
            </select>

            <button className="admin-btn" onClick={handleCreateTour}>
              Создать экскурсию
            </button>

            <div className="admin-list">
              {tours.map(t => (
                <div key={t.id} className="admin-item">
                  <span>{t.title}</span>
                  <div className="admin-actions">
                    <img src="/assets/svg/pen.svg" alt="Редактировать"
                      onClick={() => handleEditTour(t)} />
                    <img src="/assets/svg/bin.svg" alt="Удалить"
                      onClick={() => handleDeleteTour(t.id)} />
                  </div>
                </div>
              ))}
            </div>
          </section>

          {/* ===== COUNTRIES ===== */}
          <section className="admin-card">
            <h2>Страны</h2>

            <input
              placeholder="Название страны"
              value={newCountry}
              onChange={e => setNewCountry(e.target.value)}
            />

            <button
              className="admin-btn"
              onClick={async () => {
                if (!newCountry.trim()) return;
                await createCountry(newCountry.trim());
                setNewCountry('');
                loadCountries();
              }}
            >
              Добавить
            </button>

            <div className="admin-list">
              {countries.map(c => (
                <div key={c.id} className="admin-item">
                  <span>{c.name}</span>
                  <div className="admin-actions">
                    <img
                      src="/assets/svg/pen.svg"
                      alt="Редактировать"
                      onClick={async () => {
                        const name = prompt('Новое название', c.name);
                        if (!name) return;
                        await updateCountry(c.id, name);
                        loadCountries();
                      }}
                    />
                    <img
                      src="/assets/svg/bin.svg"
                      alt="Удалить"
                      onClick={async () => {
                        if (!window.confirm('Удалить страну?')) return;
                        await deleteCountry(c.id);
                        loadCountries();
                      }}
                    />
                  </div>
                </div>
              ))}
            </div>
          </section>

          {/* ===== CITIES ===== */}
          <section className="admin-card">
            <h2>Города</h2>

            <input
              placeholder="Название города"
              value={newCity}
              onChange={e => setNewCity(e.target.value)}
            />

            <select
              value={cityCountryId}
              onChange={e => setCityCountryId(e.target.value)}
            >
              <option value="">Страна</option>
              {countries.map(c => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>

            <button
              className="admin-btn"
              onClick={async () => {
                if (!newCity || !cityCountryId) return;
                await createCity({
                  name: newCity,
                  countryId: Number(cityCountryId)
                });
                setNewCity('');
                setCityCountryId('');
                loadCities();
              }}
            >
              Добавить
            </button>

            <div className="admin-list">
              {cities.map(city => (
                <div key={city.id} className="admin-item">
                  <span>
                    {city.name} ({city.country?.name})
                  </span>
                  <div className="admin-actions">
                    <img
                      src="/assets/svg/bin.svg"
                      alt="Удалить"
                      onClick={async () => {
                        if (!window.confirm('Удалить город?')) return;
                        await deleteCity(city.id);
                        loadCities();
                      }}
                    />
                  </div>
                </div>
              ))}
            </div>
          </section>

          {/* ===== CATEGORIES ===== */}
          <section className="admin-card">
            <h2>Категории</h2>

            <input
              placeholder="Название категории"
              value={newCategory}
              onChange={e => setNewCategory(e.target.value)}
            />

            <button
              className="admin-btn"
              onClick={async () => {
                if (!newCategory.trim()) return;
                await createCategory(newCategory.trim());
                setNewCategory('');
                loadCategories();
              }}
            >
              Добавить
            </button>

            <div className="admin-list">
              {categories.map(cat => (
                <div key={cat.id} className="admin-item">
                  <span>{cat.name}</span>
                  <div className="admin-actions">
                    <img
                      src="/assets/svg/pen.svg"
                      alt="Редактировать"
                      onClick={async () => {
                        const name = prompt('Новое название', cat.name);
                        if (!name) return;
                        await updateCategory(cat.id, name);
                        loadCategories();
                      }}
                    />
                    <img
                      src="/assets/svg/bin.svg"
                      alt="Удалить"
                      onClick={async () => {
                        if (!window.confirm('Удалить категорию?')) return;
                        await deleteCategory(cat.id);
                        loadCategories();
                      }}
                    />
                  </div>
                </div>
              ))}
            </div>
          </section>

          {/* ===== OPERATORS ===== */}
          <section className="admin-card">
            <h2>Туроператоры</h2>

            <input
              placeholder="Название туроператора"
              value={newOperator}
              onChange={e => setNewOperator(e.target.value)}
            />

            <button
              className="admin-btn"
              onClick={async () => {
                if (!newOperator.trim()) return;
                await createTourOperator(newOperator.trim());
                setNewOperator('');
                loadOperators();
              }}
            >
              Добавить
            </button>

            <div className="admin-list">
              {operators.map(op => (
                <div key={op.id} className="admin-item">
                  <span>{op.name}</span>
                  <div className="admin-actions">
                    <img
                      src="/assets/svg/pen.svg"
                      alt="Редактировать"
                      onClick={async () => {
                        const name = prompt('Новое название', op.name);
                        if (!name) return;
                        await updateTourOperator(op.id, name);
                        loadOperators();
                      }}
                    />
                    <img
                      src="/assets/svg/bin.svg"
                      alt="Удалить"
                      onClick={async () => {
                        if (!window.confirm('Удалить туроператора?')) return;
                        await deleteTourOperator(op.id);
                        loadOperators();
                      }}
                    />
                  </div>
                </div>
              ))}
            </div>
          </section>

          {/* ===== TAGS ===== */}
          <section className="admin-card">
            <h2>Теги</h2>

            <input
              placeholder="Название тега"
              value={newTag}
              onChange={e => setNewTag(e.target.value)}
            />

            <button className="admin-btn" onClick={handleAddTag}>
              Добавить
            </button>

            <div className="admin-list">
              {tags.map(tag => (
                <div key={tag.id} className="admin-item">
                  <span>{tag.name}</span>
                  <div className="admin-actions">
                    <img
                      src="/assets/svg/pen.svg"
                      alt="Редактировать"
                      onClick={() => handleEditTag(tag)}
                    />
                    <img
                      src="/assets/svg/bin.svg"
                      alt="Удалить"
                      onClick={() => handleDeleteTag(tag.id)}
                    />
                  </div>
                </div>
              ))}
            </div>
          </section>

        </div>

        <button className="admin-report-btn">
          Скачать PDF-отчёт
        </button>
      </div>
    </div>
  );
};

export default AdminPanel;
